const saved = new Map();
let charges = 0;

async function charge(amount) {
  await new Promise((r) => setTimeout(r, 10));
  charges++;
  return { id: charges, amount };
}

async function pay(key, amount) {
  if (saved.has(key)) return saved.get(key);
  const result = await charge(amount);
  saved.set(key, result);
  return result;
}

