const LIMIT = 3;
const WINDOW = 60; // seconds
const counts = new Map();

function allow(client, t) {
  const key = `${client}:${Math.floor(t / WINDOW)}`;
  const n = (counts.get(key) ?? 0) + 1;
  counts.set(key, n);
  return n <= LIMIT;
}

