const cache = new Map();
let price = 100; // the database row
let now = 0;     // seconds

function getPrice() {
  const hit = cache.get("price");
  if (hit && hit.expires > now) return hit.value;
  cache.set("price", { value: price, expires: now + 60 });
  return price;
}

