async function getUser(id) {
  const key = `user:${id}`;
  const cached = await cache.get(key);
  if (cached) return cached;
  const user = await db.users.find(id);
  await cache.set(key, user, { ttl: 3600 });
  return user;
}

async function renameUser(id, name) {
  await cache.del(`user:${id}`);
  await db.users.update(id, { name });
}

async function placeOrder(req, res) {
  const tx = await db.begin();
  try {
    const order = await tx.orders.insert(req.body);
    await queue.add("send-receipt", {
      email: req.body.email, total: order.total });
    await tx.stock.reserve(order.items);
    await tx.commit();
    res.status(201).json(order);
  } catch (err) {
    await tx.rollback();
    throw err;
  }
}

